input.newString:
function drawShip() {
    // Draw ship as a triangle pointing in movement direction
    const angle = Math.atan2(ship.dy || 0, ship.dx || 0);
    ctx.save();
    ctx.translate(ship.x, ship.y);
    ctx.rotate(angle);
    const size = ship.r * 2;
    ctx.fillStyle = '#0f0';
    ctx.beginPath();
    ctx.moveTo(0, -size / 2);
    ctx.lineTo(size / 2, size / 2);
    ctx.lineTo(-size / 2, size / 2);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

